                  shape: BoxShape.circle,
                ),
              ),
              const SizedBox(width: 6),
              Text(
                context.l10n.networkOnlineCount(live),
                style: TextStyle(fontSize: 12, color: colors.dim),
              ),
            ],
          ),
        ),
        Expanded(
          child: session == null
              ? Center(
                  child: Text(
                    context.l10n.networkConnecting,
                    style: TextStyle(color: colors.dim),
